import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

// 本卡实际变量根：stat_data.jiayin_ntr
// MagVarUpdate 的命令路径从 jiayin_ntr 开始，例如：
// _.set('jiayin_ntr.阶段.当前阶段', 'P1', 'P2');
const KnowledgeState = z.enum([
  '知道',
  '装不知',
  '不知',
  '半知',
  '被瞒',
]);

// 正式事实集合：被写名是第 11 项，所有角色都保留该键；未知时值为“不知”。
const FormalFacts = [
  '结缘书被偷', '黑皮身份与能力', '妈妈沦陷', '小姨约炮',
  '软软变心', '姐姐赌局与关系', '妹妹被调教/开苞', '全球直播',
  '守护神被骗', '沐昕狗奴化', '被写名',
];

const CharacterKnowledge = z.object({
  '结缘书被偷': KnowledgeState.prefault('不知'),
  '黑皮身份与能力': KnowledgeState.prefault('不知'),
  '妈妈沦陷': KnowledgeState.prefault('不知'),
  '小姨约炮': KnowledgeState.prefault('不知'),
  '软软变心': KnowledgeState.prefault('不知'),
  '姐姐赌局与关系': KnowledgeState.prefault('不知'),
  '妹妹被调教/开苞': KnowledgeState.prefault('不知'),
  '全球直播': KnowledgeState.prefault('不知'),
  '守护神被骗': KnowledgeState.prefault('不知'),
  '沐昕狗奴化': KnowledgeState.prefault('不知'),
  '被写名': KnowledgeState.prefault('不知'),
}).strict().prefault({});

export const Schema = z.object({
  jiayin_ntr: z.object({
    世界: z.object({
      当前时间: z.string().prefault('深夜十一点半'),
      当前地点: z.string().prefault('沐昕房间'),
      私密等级: z.enum(['menu', 'public', 'semi_private', 'private']).prefault('private'),
      私密度: z.string().prefault('私密'),
      天气: z.string().prefault('夜'),
    }).prefault({}),

    主角: z.object({
      体力: z.string().prefault('充沛'),
      穿着: z.string().prefault('待初始化'),
      心理状态: z.string().prefault('焦虑而清醒'),
      已知事实: z.array(z.string()).prefault([]),
      绿帽癖倾向: z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(0),
    }).prefault({}),

    阶段: z.object({
      当前阶段: z.enum(['MENU', 'P0', 'P1', 'P2', 'P3', 'P4', 'P5', 'P6']).prefault('MENU'),
      已触发节点: z.array(z.string()).prefault([]),
    }).prefault({}),

    情报: z.object({
      // 不再截断为 5 条；终端和未读数均从同一帖子流计算。
      帖子流: z.array(z.object({
        帖子ID: z.string().prefault(''),
        发帖人: z.string().prefault(''),
        类型: z.string().prefault(''),
        涉及角色: z.string().prefault(''),
        标题: z.string().prefault(''),
        摘要: z.string().prefault(''),
        出现时间: z.string().prefault(''),
        证据等级: z.string().prefault('未评级'),
        获得渠道: z.string().prefault('论坛'),
        沐昕已读: z.boolean().prefault(false),
        聊天楼层: z.coerce.number().prefault(-1),
      })).prefault([]),
    }).prefault({}),

    // 事实级知情矩阵：角色 -> 事实 -> 五态之一。
    知情矩阵: z.object({
    沐温凝: CharacterKnowledge,
    沐嫣染: CharacterKnowledge,
    沐冰铃: CharacterKnowledge,
    小姨: CharacterKnowledge,
    软软: CharacterKnowledge,
    守护神: CharacterKnowledge,
    沐昕: CharacterKnowledge,
    黑皮小鬼: CharacterKnowledge,
    }).prefault({}),

    沦陷进度: z.object({
    沐温凝: z.object({
      堕落值: z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(0),
      阶段标签: z.string().prefault(''),
      最近事件: z.string().prefault(''),
    }).prefault({}),
    沐嫣染: z.object({
      堕落值: z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(0),
      阶段标签: z.string().prefault(''),
      最近事件: z.string().prefault(''),
    }).prefault({}),
    沐冰铃: z.object({
      堕落值: z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(0),
      阶段标签: z.string().prefault(''),
      最近事件: z.string().prefault(''),
    }).prefault({}),
    小姨: z.object({
      堕落值: z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(0),
      阶段标签: z.string().prefault(''),
      最近事件: z.string().prefault(''),
    }).prefault({}),
    软软: z.object({
      堕落值: z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(0),
      阶段标签: z.string().prefault(''),
      最近事件: z.string().prefault(''),
    }).prefault({}),
    守护神: z.object({
      堕落值: z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(0),
      阶段标签: z.string().prefault(''),
      最近事件: z.string().prefault(''),
    }).prefault({}),
    沐昕绿奴化: z.object({
      堕落值: z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(0),
      阶段标签: z.string().prefault(''),
      最近事件: z.string().prefault(''),
    }).prefault({}),
    }).prefault({}),

    在场: z.object({
      场景: z.string().prefault('独处'),
      角色: z.array(z.string()).prefault(['沐昕']),
      黑皮在场: z.boolean().prefault(false),
    }).prefault({}),
  }).prefault({}),
});

$(() => {
  registerMvuSchema(Schema);
});

// 沦陷进度程序护栏：拒绝堕落值回退，兼容真实 MVU 更新事件与无事件写入
try {
  const ROOT = 'stat_data.jiayin_ntr';
  const VALUE_PATHS = [
    '沦陷进度.沐温凝.堕落值', '沦陷进度.沐嫣染.堕落值', '沦陷进度.沐冰铃.堕落值',
    '沦陷进度.小姨.堕落值', '沦陷进度.软软.堕落值', '沦陷进度.守护神.堕落值',
    '沦陷进度.沐昕绿奴化.堕落值',
  ];
  const PATH_RE = /^(?:jiayin_ntr\.)?沦陷进度\.[^.]+\.堕落值$/;
  const unwrap = value => Array.isArray(value) && value.length === 2 ? value[0] : value;
  const getPath = (obj, path) => String(path).split('.').reduce((value, key) => value == null ? undefined : value[key], obj);
  const getChatKey = () => {
    const homes = [];
    try { homes.push(globalThis); } catch (_) {}
    try { homes.push(window); } catch (_) {}
    for (const home of homes) {
      try {
        const context = home.SillyTavern?.getContext?.();
        const getter = context?.getCurrentChatId;
        const chatId = typeof getter === 'function' ? getter.call(context) : context?.chatId;
        if (typeof chatId === 'string' && chatId) return chatId;
      } catch (_) {}
    }
    return null;
  };
  const api = name => {
    const homes = [];
    try { homes.push(globalThis); } catch (_) {}
    try { homes.push(window); } catch (_) {}
    for (const home of homes) {
      if (!home) continue;
      try {
        const helper = home.TavernHelper;
        if (helper && typeof helper[name] === 'function') return helper[name].bind(helper);
      } catch (_) {}
      try { if (typeof home[name] === 'function') return home[name].bind(home); } catch (_) {}
    }
    return null;
  };
  const readLatest = async () => {
    const getVariables = api('getVariables');
    if (!getVariables) return null;
    return await Promise.resolve(getVariables({type:'message', message_id:'latest'}));
  };
  const updateLatest = async (path, value) => {
    const updateVariablesWith = api('updateVariablesWith');
    if (!updateVariablesWith) return false;
    await Promise.resolve(updateVariablesWith(draft => {
      return _.set(draft, ROOT + '.' + path, value);
    }, {type:'message', message_id:'latest'}));
    return true;
  };

  const timerHost = typeof window !== 'undefined' && window.parent && typeof window.parent.setInterval === 'function'
    ? window.parent
    : (typeof window !== 'undefined' ? window : globalThis);
  const buckets = timerHost.__jiayinMonotonicBuckets || Object.create(null);
  timerHost.__jiayinMonotonicBuckets = buckets;
  const getBucket = chatKey => {
    if (typeof chatKey !== 'string' || !chatKey) return null;
    if (!buckets[chatKey]) buckets[chatKey] = {previous: Object.create(null)};
    return buckets[chatKey];
  };
  const enforceCandidate = (draft, chatKey = getChatKey()) => {
    const bucket = getBucket(chatKey);
    if (!bucket) return draft;
    const previous = bucket.previous;
    const state = getPath(draft, ROOT);
    if (!state) return draft;
    for (const path of VALUE_PATHS) {
      const current = Number(unwrap(getPath(state, path)));
      if (!Number.isFinite(current)) continue;
      const prior = previous[path];
      if (Number.isFinite(prior) && current < prior) {
        _.set(draft, ROOT + '.' + path, prior);
        console.warn('[隐奸状态护栏] 提交前拒绝堕落值回退：' + path + ' ' + current + ' -> ' + prior);
        continue;
      }
      previous[path] = Math.max(prior ?? -Infinity, current);
    }
    return draft;
  };
  const wrapUpdater = target => {
    if (!target || typeof target.updateVariablesWith !== 'function') return;
    const original = target.updateVariablesWith;
    if (original.__jiayinMonotonicWrapped) return;
    const wrapped = async function(updater, options) {
      const chatKey = getChatKey();
      return await original.call(this, async draft => {
        const candidate = typeof updater === 'function' ? await updater(draft) : draft;
        return enforceCandidate(candidate ?? draft, chatKey);
      }, options);
    };
    try { Object.defineProperty(wrapped, '__jiayinMonotonicWrapped', {value:true}); } catch (_) {}
    target.updateVariablesWith = wrapped;
  };
  for (const home of [globalThis, window]) {
    try { wrapUpdater(home && home.TavernHelper); } catch (_) {}
    try { wrapUpdater(home); } catch (_) {}
  }
  let reconciling = false;
  const capture = async () => {
    const chatKey = getChatKey();
    const bucket = getBucket(chatKey);
    if (!bucket) return;
    const latest = await readLatest();
    if (getChatKey() !== chatKey) return;
    const state = getPath(latest, ROOT);
    if (!state) return;
    for (const path of VALUE_PATHS) {
      const number = Number(unwrap(getPath(state, path)));
      if (Number.isFinite(number)) bucket.previous[path] = Math.max(bucket.previous[path] ?? -Infinity, number);
    }
  };
  const reconcile = async () => {
    if (reconciling) return;
    const chatKey = getChatKey();
    const bucket = getBucket(chatKey);
    if (!bucket) return;
    reconciling = true;
    try {
      const latest = await readLatest();
      if (getChatKey() !== chatKey) return;
      const state = getPath(latest, ROOT);
      if (!state) return;
      for (const path of VALUE_PATHS) {
        if (getChatKey() !== chatKey) return;
        const current = Number(unwrap(getPath(state, path)));
        if (!Number.isFinite(current)) continue;
        const prior = bucket.previous[path];
        if (Number.isFinite(prior) && current < prior) {
          await updateLatest(path, prior);
          console.warn('[隐奸状态护栏] 拒绝堕落值回退：' + path + ' ' + current + ' -> ' + prior);
          continue;
        }
        bucket.previous[path] = Math.max(prior ?? -Infinity, current);
      }
    } catch (error) {
      console.error('[隐奸状态护栏] 重检查失败', error);
    } finally {
      reconciling = false;
    }
  };
  const directHandler = (statData, path, oldValue, newValue) => {
    if (typeof path !== 'string' || !PATH_RE.test(path)) return;
    const oldNumber = Number(unwrap(oldValue));
    const newNumber = Number(unwrap(newValue));
    if (!Number.isFinite(oldNumber) || !Number.isFinite(newNumber) || newNumber >= oldNumber) return;
    try {
      _.set(statData, path, oldNumber);
      console.warn('[隐奸状态护栏] 拒绝堕落值回退：' + path + ' ' + newNumber + ' -> ' + oldNumber);
    } catch (error) {
      console.error('[隐奸状态护栏] 事件回退写入失败', error);
    }
  };
  const off = [];
  const eventOn = api('eventOn');
  if (eventOn) {
    for (const name of ['mag_variable_updated', 'mag_variable_update_ended', 'mag_variable_initialized']) {
      try {
        const cleanup = eventOn(name, name === 'mag_variable_updated' ? directHandler : reconcile);
        if (typeof cleanup === 'function') off.push(cleanup);
      } catch (_) {}
    }
  }
  if (timerHost.__jiayinMonotonicStop) { try { timerHost.__jiayinMonotonicStop(); } catch (_) {} }
  if (timerHost.__jiayinMonotonicTimer) { try { timerHost.clearTimeout(timerHost.__jiayinMonotonicTimer); } catch (_) {} }
  let stopped = false;
  timerHost.__jiayinMonotonicOff = () => off.forEach(cleanup => { try { cleanup(); } catch (_) {} });
  timerHost.__jiayinMonotonicStop = () => {
    stopped = true;
    try { timerHost.clearTimeout(timerHost.__jiayinMonotonicTimer); } catch (_) {}
    try { timerHost.__jiayinMonotonicOff(); } catch (_) {}
  };
  const tick = async () => {
    if (stopped) return;
    try {
      await reconcile();
      await capture();
    } catch (error) {
      console.error('[隐奸状态护栏] 周期检查失败', error);
    } finally {
      if (!stopped) timerHost.__jiayinMonotonicTimer = timerHost.setTimeout(tick, 2000);
    }
  };
  timerHost.__jiayinMonotonicTimer = timerHost.setTimeout(tick, 2000);
  void capture();
} catch (error) {
  console.error('[隐奸状态护栏] 初始化失败', error);
}

// 隐奸情报终端 v3 —— 玩家调查 UI；玩家模式不读取后台进度/知情矩阵进行渲染
$(errorCatched(async () => {
  const ID = 'jiayin-orb';
  let pwin, pdoc;
  try {
    const localWin = typeof window !== 'undefined' ? window : globalThis;
    pwin = localWin.parent && localWin.parent.window ? localWin.parent : localWin;
    pdoc = pwin.document || document;
  } catch (_) {
    pwin = window;
    pdoc = document;
  }

  try { if (typeof pwin.__jiayinOrbCleanup === 'function') pwin.__jiayinOrbCleanup(); } catch (_) {}
  try { if (pwin.__jiayinOrbTimer) pwin.clearInterval(pwin.__jiayinOrbTimer); } catch (_) {}
  pdoc.getElementById(ID)?.remove();
  pdoc.getElementById(ID + '-style')?.remove();

  const style = pdoc.createElement('style');
  style.id = ID + '-style';
  style.textContent = `
#${ID}{position:fixed;left:0;top:0;width:0;height:0;z-index:9999;font-family:"Microsoft YaHei","PingFang SC",sans-serif;user-select:none}
#${ID} .jo-ball{width:54px;height:54px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#232b42,#0b0e16);border:2px solid #3a6ea8;color:#ffd9e0;display:flex;flex-direction:column;align-items:center;justify-content:center;cursor:grab;box-shadow:0 4px 20px rgba(0,0,0,.7);font-size:16px;font-weight:800;line-height:1.15;position:relative;touch-action:none}
#${ID} .jo-ball:active,#${ID} .jo-titlebar:active{cursor:grabbing}
#${ID} .jo-ball small{font-size:9px;color:#8fa7c9;font-weight:400}
#${ID} .jo-badge{position:absolute;top:-4px;right:-4px;min-width:20px;height:20px;border-radius:10px;background:#d9405c;color:#fff;font-size:11px;font-weight:700;display:none;align-items:center;justify-content:center;padding:0 5px;box-shadow:0 0 8px rgba(217,64,92,.8)}
#${ID}.jo-has-unread .jo-badge{display:flex}
#${ID} .jo-panel{display:none;position:fixed;width:min(340px,calc(100vw - 20px));max-height:min(70vh,560px);overflow-y:auto;background:#101318;border:1px solid #2a2f3a;border-radius:12px;color:#d8dbe0;font-size:13px;line-height:1.7;box-shadow:0 10px 34px rgba(0,0,0,.8)}
#${ID}.jo-open .jo-panel{display:block}
#${ID} .jo-titlebar{display:flex;align-items:center;gap:8px;padding:9px 12px;border-bottom:1px solid #2a2f3a;cursor:grab;background:#151a28;border-radius:12px 12px 0 0;touch-action:none}
#${ID} .jo-title{font-weight:700;color:#ffb347;font-size:13.5px;flex:1}
#${ID} .jo-tabs{display:flex;gap:4px;padding:6px 10px;border-bottom:1px dashed #2a2f3a}
#${ID} .jo-tab{flex:1;text-align:center;padding:4px 0;font-size:12.5px;color:#9aa3b2;border:1px solid transparent;border-radius:8px;cursor:pointer}
#${ID} .jo-tab.jo-on{color:#ffd9e0;background:#1d2436;border-color:#3a3f55}
#${ID} .jo-body{padding:10px 12px}
#${ID} .jo-sec{font-size:12px;color:#ffb347;font-weight:700;margin:8px 0 4px;border-left:3px solid #d9405c;padding-left:8px}
#${ID} .jo-line{font-size:12.5px;color:#c9cede;padding:2px 0}
#${ID} .jo-line b{color:#ffd9e0}
#${ID} .jo-post{background:#151a28;border:1px solid #232833;border-radius:8px;padding:6px 9px;margin:5px 0;font-size:12px}
#${ID} .jo-post .jo-pu{color:#ff9db0;font-weight:600}.jo-post .jo-pt{color:#8fa7c9;margin-left:6px}.jo-post .jo-pr{color:#6b7488;margin-left:6px}
#${ID} .jo-post.jo-read{opacity:.55}
#${ID} .jo-empty{color:#5b6472;font-size:12px;padding:6px 0}
#${ID} .jo-fact{list-style:none;padding:0;margin:0}#${ID} .jo-fact li{padding:3px 0 3px 14px;position:relative;font-size:12.5px;color:#c9cede}#${ID} .jo-fact li::before{content:"▸";position:absolute;left:0;color:#d9405c}
#${ID} .jo-node{display:inline-block;background:#1d2436;border:1px solid #2c3347;border-radius:10px;padding:1px 8px;margin:2px 3px 2px 0;font-size:11.5px;color:#9aa3b2}
#${ID} .jo-foot{padding:6px 12px 9px;font-size:11px;color:#5b6472;border-top:1px dashed #2a2f3a;display:flex;justify-content:space-between}
@media(max-width:480px){#${ID} .jo-panel{font-size:12px}}
`;
  pdoc.head.appendChild(style);

  const root = pdoc.createElement('div');
  root.id = ID;
  root.innerHTML = '<div class="jo-ball" role="button" aria-label="打开隐奸情报终端">P?<small>隐奸</small><span class="jo-badge">0</span></div>' +
    '<div class="jo-panel"><div class="jo-titlebar"><span class="jo-title">隐奸情报终端</span></div>' +
    '<div class="jo-tabs"><div class="jo-tab jo-on" data-tab="info">情报</div><div class="jo-tab" data-tab="ppl">人物</div><div class="jo-tab" data-tab="prog">进度</div></div>' +
    '<div class="jo-body"></div><div class="jo-foot"><span>玩家视角</span><span>拖动移动 · 双击复位</span></div></div>';
  pdoc.body.appendChild(root);

  const ball = root.querySelector('.jo-ball');
  const panel = root.querySelector('.jo-panel');
  const titlebar = root.querySelector('.jo-titlebar');
  const body = root.querySelector('.jo-body');
  const badge = root.querySelector('.jo-badge');
  const STAGE_NAMES = {MENU:'图鉴菜单',P0:'幸福期',P1:'失窃与写名期',P2:'窥帖沦陷期',P3:'当面羞辱期',P4:'操纵与直播期',P5:'守护神沦陷期',P6:'开放终局'};
  const PEOPLE = [
    ['沐温凝','妈妈','沐温凝'],['沐嫣染','姐姐','沐嫣染'],['沐冰铃','妹妹','沐冰铃'],
    ['小姨','小姨','小姨'],['软软','软软','软软'],['守护神','守护神','守护神'],['沐昕','沐昕','沐昕绿奴化']
  ];
  const RISK = {'菜单':'#68758f','公开':'#3a6ea8','家庭公开':'#4f8f78','半公开':'#b8862e','半私密':'#d07a39','私密':'#c0392b','家庭公开·桌下隐秘':'#b84d62'};
  const RISK_BY_LEVEL = {menu:'#68758f',public:'#3a6ea8',semi_private:'#d07a39',private:'#c0392b'};
  const clean = v => (Array.isArray(v) && v.length === 2 && typeof v[1] === 'string') ? v[0] : v;
  const esc = v => String(clean(v) == null ? '' : clean(v)).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const pathGet = (obj, path) => String(path).split('.').reduce((a,k) => a == null ? undefined : a[k], obj);
  const stateFrom = value => {
    if (!value || typeof value !== 'object') return null;
    const candidates = [pathGet(value,'stat_data.jiayin_ntr'), pathGet(value,'stat_data')?.jiayin_ntr, value.jiayin_ntr];
    for (const candidate of candidates) if (candidate && typeof candidate === 'object') return candidate;
    if (value.世界 || value.主角 || value.阶段 || value.情报) return value;
    return null;
  };
  // 兼容酒馆助手不同运行容器：顶层函数、globalThis、主窗口 TavernHelper。
  function apiMethod(name){
    const homes=[];
    try { homes.push(typeof globalThis !== 'undefined' ? globalThis : null); } catch (_) {}
    try { homes.push(pwin); } catch (_) {}
    try { homes.push(typeof window !== 'undefined' ? window : null); } catch (_) {}
    for (const home of homes) {
      if (!home) continue;
      try {
        const helper=home.TavernHelper;
        if (helper && typeof helper[name] === 'function') return helper[name].bind(helper);
      } catch (_) {}
      try { if (typeof home[name] === 'function') return home[name].bind(home); } catch (_) {}
    }
    return null;
  }
  async function readState(){
    const calls=[];
    const all=apiMethod('getAllVariables');
    const latest=apiMethod('getVariables');
    if (all) calls.push(() => all());
