      PEOPLE.forEach(([key,label])=>{const related=posts.filter(p=>String(clean(p.涉及角色)||'').includes(key)||String(clean(p.涉及角色)||'')==='全家');const readRelated=related.filter(p=>clean(p.沐昕已读));const readN=readRelated.length;const last=readRelated[readRelated.length-1];html+='<div class="jo-line"><b>'+esc(label)+'</b> · 已读相关情报 '+readN+' 条';if(last)html+='<br><span style="color:#8fa7c9">最近：'+esc(last.类型||'帖子')+'（涉及'+esc(last.涉及角色||'?')+'）</span>';html+='<br><span style="color:#6b7488">观察：'+(readN?'已发现异常痕迹':'暂无异常线索')+'</span></div>';});
      html+='<div class="jo-empty">玩家模式只根据已读帖子生成观察；真实进度和知情矩阵不会显示。</div>';    } else {
      html+='<div class="jo-sec">阶段进度</div><div class="jo-line">当前阶段：<b>'+esc(stage)+' '+esc(STAGE_NAMES[stage]||'')+'</b></div><div class="jo-line">已触发节点：'+nodes.length+' 个</div><div class="jo-line">最近节点：'+esc(nodes.length?nodes[nodes.length-1]:'--')+'</div>';
      if(nodes.length>1)html+='<div>'+nodes.map(n=>'<span class="jo-node">'+esc(n)+'</span>').join('')+'</div>';
      html+='<div class="jo-sec">情报流</div><div class="jo-line">帖子总数：'+posts.length+' 条（未读 '+unread+'）</div><div class="jo-line">线索载体：结缘书 / 论坛 / 照片 / 直播</div>';
    }
    body.innerHTML=html; if(root.classList.contains('jo-open'))layoutPanel();
  }

  const unsubs=[];
  function onEvent(name,fn){
    try{
      if(!name) return;
      const eventFn=apiMethod('eventOn');
      if(eventFn){const off=eventFn(name,fn);if(typeof off==='function')unsubs.push(off);}
    }catch(_){}
  }
  try{
    const events=(typeof tavern_events!=='undefined'&&tavern_events) || pwin.tavern_events || {};
    ['MESSAGE_RECEIVED','MESSAGE_UPDATED','CHAT_CHANGED'].forEach(k=>onEvent(events[k]||k,()=>{void render();}));
  }catch(_){ }
  onEvent('mag_variable_update_ended',()=>{void render();}); onEvent('mag_variable_initialized',()=>{void render();});
  const onResize=()=>{pos=clamp(pos);applyPos();if(root.classList.contains('jo-open'))layoutPanel();}; pwin.addEventListener('resize',onResize);
  pwin.__jiayinOrbTimer=pwin.setInterval(()=>{void render();},2000);
  pwin.__jiayinOrbCleanup=()=>{try{pwin.clearInterval(pwin.__jiayinOrbTimer);}catch(_){};unsubs.forEach(off=>{try{off();}catch(_){} });try{pwin.removeEventListener('resize',onResize);}catch(_){};root.remove();style.remove();};
  loadPos(); applyPos(); void render();
}));

// 阶段路由控制器 v3 —— 硬闭环：按 MVU 当前阶段退役历史中的旧阶段路由标题
// 接口：getAllVariables / getChatMessages / setChatMessages / eventOn(tavern_events)
const STAGE_TITLES = {
  'P0': '【开场：生日宴上的结缘书｜P0】',
  'P1': '【开场：结缘书失窃之夜｜P1】',
  'P2': '【开场：论坛上的第一帖｜P2】',
  'P3': '【开场：姐姐的赌局｜P3】',
  'P4': '【开场：妹妹的直播｜P4】',
  'P5': '【开场：守护神的项圈｜P5】',
  'P6': '【开场：餐桌下的狗奴｜P6】',
};
const RETIRED_MARK = '【已退役·阶段路由】';
const TITLE_RE = /【开场：[^】]+｜P[0-6]】/g;

let routerRunning = false;

function routerApi(name){
  const homes=[];
  try { homes.push(typeof globalThis !== 'undefined' ? globalThis : null); } catch (_) {}
  try { if (typeof window !== 'undefined') homes.push(window); } catch (_) {}
  for (const home of homes) {
    if (!home) continue;
    try { const helper=home.TavernHelper; if (helper && typeof helper[name] === 'function') return helper[name].bind(helper); } catch (_) {}
    try { if (typeof home[name] === 'function') return home[name].bind(home); } catch (_) {}
  }
  return null;
}

async function routerCall(name, ...args) {
  const fn=routerApi(name);
  return fn ? await Promise.resolve(fn(...args)) : null;
}

async function stageRouterTick() {
  if (routerRunning) return;
  routerRunning = true;

  try {
    // 1) 读变量（MVU 合并表，多级 fallback）
    const variables = await routerCall('getAllVariables') ||
                      await routerCall('getVariables', {type:'message', message_id:'latest'}) || {};
    const readPath=(obj,path)=>String(path).split('.').reduce((a,k)=>a==null?undefined:a[k],obj);
    const stage = readPath(variables, 'stat_data.jiayin_ntr.阶段.当前阶段') ??
                  readPath(variables, 'jiayin_ntr.阶段.当前阶段') ??
                  readPath(variables, '阶段.当前阶段');
    const currentTitle = STAGE_TITLES[stage];
    if (!currentTitle) return;  // 首轮未初始化：不动任何消息

    // 2) 读全部消息（官方消息结构：message_id / message）
    const messages = await routerCall('getChatMessages', '0-{{lastMessageId}}');
    if (!Array.isArray(messages)) return;
    const updates = [];

    for (const item of messages) {
      if (!item || typeof item.message !== 'string') continue;
      if (!TITLE_RE.test(item.message)) continue;
      const replaced = item.message.replace(TITLE_RE, (title) => (title === currentTitle ? title : RETIRED_MARK));
      if (replaced !== item.message) {
        updates.push({ message_id: item.message_id, message: replaced });
      }
    }

    // 3) 批量写回
    if (updates.length > 0) {
      await routerCall('setChatMessages', updates, { refresh: 'none' });
      console.info('[阶段路由控制器] 当前阶段=' + stage + '，退役楼层=' + updates.length);
    }
  } catch (error) {
    console.error('[阶段路由控制器] 执行失败', error);
  } finally {
    routerRunning = false;
  }
}

// 绑定生成前事件（幂等，多事件兜底；退役操作重复执行无害）
try {
  let boundCount = 0;
  const eventFn=routerApi('eventOn');
  const events=(typeof tavern_events !== 'undefined' && tavern_events) ||
               (typeof globalThis !== 'undefined' && globalThis.tavern_events) || {};
  if (eventFn) {
    for (const eventName of [
      events.MESSAGE_SENT || 'MESSAGE_SENT',
      events.GENERATE_AFTER_COMBINE_PROMPTS || 'GENERATE_AFTER_COMBINE_PROMPTS',
      events.MESSAGE_RECEIVED || 'MESSAGE_RECEIVED',
    ]) {
      if (!eventName) continue;
      eventFn(eventName, stageRouterTick);
      boundCount++;
    }
  }
  if (boundCount > 0) {
    console.info('[阶段路由控制器] 已绑定事件=' + boundCount);
  } else {
    console.warn('[阶段路由控制器] 未找到可用事件，仅使用软闭环');
  }
} catch (e) {
  console.error('[阶段路由控制器] 事件绑定失败', e);
}
